#include <cstdint>
#include <optional>

std::optional<std::uint64_t> effectiveAddress(std::uint64_t base, std::uint64_t index, int scale, std::int64_t displacement)
{
    if (scale != 1 && scale != 2 && scale != 4 && scale != 8) return std::nullopt;
    return base + index * static_cast<std::uint64_t>(scale) + static_cast<std::uint64_t>(displacement);   // unsigned: wraps like the CPU
}

std::uint32_t widen(std::uint8_t byte, bool isSigned)
{
    if (isSigned) return static_cast<std::uint32_t>(static_cast<std::int32_t>(static_cast<std::int8_t>(byte)));
    return byte;
}

unitTests:
TEST("array indexing") { CHECK_EQ(*effectiveAddress(0x2000, 3, 4, 0), 0x200Cull); }
TEST("a member offset") { CHECK_EQ(*effectiveAddress(0x5000, 0, 1, 0x18), 0x5018ull); }
TEST("a negative displacement") { CHECK_EQ(*effectiveAddress(0x1000, 0, 1, -8), 0xFF8ull); }
TEST("everything at once") { CHECK_EQ(*effectiveAddress(0x10000, 5, 8, 0x10), 0x10038ull); }
TEST("wraps round") { CHECK_EQ(*effectiveAddress(0xFFFFFFFFFFFFFFFFull, 1, 1, 0), 0ull); }
TEST("bad scales") { CHECK(!effectiveAddress(0, 1, 3, 0).has_value()); CHECK(!effectiveAddress(0, 1, 16, 0).has_value()); }
TEST("zero extension") { CHECK_EQ(widen(0xFE, false), 0xFEu); CHECK_EQ(widen(0x7F, false), 0x7Fu); }
TEST("sign extension") { CHECK_EQ(widen(0xFE, true), 0xFFFFFFFEu); CHECK_EQ(widen(0x7F, true), 0x7Fu); CHECK_EQ(widen(0x80, true), 0xFFFFFF80u); }

